/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    OMGInboundMessageTable                      inboundMessageTable;
    OMGTutorialLedgerJournalHeaderDataContract  headerContract;
    List                                        lineList;      
    OMGTutorialLedgerJournalLineDataContract    lineContract;
    ;

    inboundMessageTable = OMGInboundMessageTable::findRecId(5637223820);


    headerContract = FormJsonSerializer::deserializeObject(classNum(OMGTutorialLedgerJournalHeaderDataContract), inboundMessageTable.Message);

    lineList = headerContract.parmLines();

    ListEnumerator  lineListEnumerator = lineList.getEnumerator();

    while (lineListEnumerator.moveNext())
    {
        lineContract = lineListEnumerator.current();
    }

}
